import './App.css';

import { useEffect, useState } from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import config from './config.json';
import { LanguageContext } from './multilang/LanguageContext';
import { Languages } from './multilang/Languages';
import { FloatingLanguageSelector } from './components/LanguageSelectors';
import HomePage from './pages/HomePage';
import { GradientSvgDef } from './styles';

function App() {
  const [currentLanguage, setCurrentLanguage] = useState(() => {
    const savedLanguageId = localStorage.getItem('language_id')
    return Languages.all().find(({ id }) => id === savedLanguageId) || Languages.ENG
  })

  useEffect(() => {
    localStorage.setItem('language_id', currentLanguage.id)
  }, [currentLanguage])

  return (
    <BrowserRouter>
      <GradientSvgDef />
      <Routes>
        <Route path="/*" element={
          <LanguageContext.Provider value={[currentLanguage, setCurrentLanguage]}>
            <HomePage />
            <FloatingLanguageSelector />
          </LanguageContext.Provider>
        } />
      </Routes>
    </BrowserRouter>
  );
}

export default App;